import json,pathlib,re
q=pathlib.Path('projects/holoen/research/qa')
for name in ['manifest.json','registry.json']:
 d=json.loads((q/name).read_text());print('\\nFILE',name)
 for k,v in d.items():
  if isinstance(v,list): print(k,'count',len(v),'sample',json.dumps(v[:2],ensure_ascii=False))
  elif isinstance(v,dict): print(k,'keys',list(v)[:10],'sample',json.dumps(dict(list(v.items())[:2]),ensure_ascii=False))
  else: print(k,v)
for p in sorted(q.glob('audit-*.md')):
 print('\\nREPORT',p.name)
 for line in p.read_text().splitlines():
  if p.name=='audit-bridge-events.md' or re.search(r'BR-|SCOPE|TIE-|UNIT-|ALIAS-|QUOTE-|CREDIT-|COVERAGE-|external|Cross-Branch|Rikka|Kanaken|KALAZ|Bara|Yakamashi|MVP|HOLOTALK|TakaMori|Kaela|Sana|V3LVET|Grindstone|Graondstone|Star Flower|HOLOTORI|incoming|packet|registry|New verified facts|Merge handoff|Open questions',line,re.I): print(line)
print('\\nRELATIONSHIP WEB')
print((q/'relationship-web.md').read_text())
PY"

