/bin/bash -lc "python - <<'PY'
import json,pathlib,re
q=pathlib.Path('projects/holoen/research/qa'); reg=json.loads((q/'registry.json').read_text()); man=json.loads((q/'manifest.json').read_text())
print('MANIFEST bridge/hash records',json.dumps({k:v for k,v in man['packets'].items() if 'tie' in k or 'event' in k})); print('FILES',len(man['files']), 'registry stored hash', man['files'].get('research/qa/registry.json'))
for group in ['cast','world','credits']:
 print('\\nREGISTRY',group)
 for x in reg[group]: print(json.dumps({k:v for k,v in x.items() if k not in ['status','status_interval']},ensure_ascii=False))
print('\\nREPORT FINDING INDEX: ID / claim / problem')
for p in sorted(q.glob('audit-*.md')):
 print('\\n'+p.name)
 for s in p.read_text().splitlines():
  if not s.startswith('| '): continue
  cols=re.split(r'(?<"'!'"\\\\)\\|',s)
  if len(cols)>7 and re.search(r'(?:BR-|SCOPE|TIE-|UNIT-|ALIAS-|QUOTE-|CREDIT-|COVERAGE-)',cols[1]): print(' / '.join(cols[i].strip() for i in [1,3,6]))
PY"

